/**
 * Creates a new caldav session
 *
 * @param {string} aUserName - The username associated with this session.
 */
constructor(aUserName) {
  this.username = aUserName;
}

get id() {
  return this.mID;
},
set id(val) {
  const setter = this.__proto__.__proto__.__lookupSetter__("id");
  val = setter.call(this, val);

  if (this.id) {
    // Some calendars created in old versions may not have a stored username,
    // and have the password stored with the calendar ID. This only matters for
    // OAuth calendars, in all other cases the password is stored by username.
    this.session = new CalDavSession(this.getProperty("username") || this.id);
  }
},

// calIChangeLog interface
get offlineStorage() {

 * form, which reduces them to just the scheme. Nothing reads these logins any
 * more, so the collapse is harmless, but the tests below still check they are
 * left alone.
 *
 * @param {string} id - The calendar or session ID the login was stored with.
 * @returns {string} The origin as the active backend stores it.
 */
function legacyOAuthOrigin(id) {
  return Services.prefs.getBoolPref("signon.storage.rust.active", false) ? "oauth:" : `oauth:${id}`;
}

/** Expired token stored with calendar ID, username set. The new token is stored with the username. */
add_task(async function testCalendarOAuth_id_and_username_expired() {
  const calendarId = "testCalendarOAuth_id_and_username_expired";
  const logins = [
    {
      ...defaultLogin,
      username: calendarId,
      password: "expired_token",
    },
  ];
  await setPref(calendarId, "username", USERNAME);
  await setLogins(logins);
  await subtest(calendarId, { username: USERNAME, reason: "no refresh token" });
  await checkAndClearLogins([logins[0], defaultLogin]);
